import{_ as r,C as i,o as d,c as s,j as t,a,E as n,ag as l}from"./chunks/framework.DMVuHR7L.js";const f=JSON.parse('{"title":"Dashboard & layout","description":"","frontmatter":{},"headers":[],"relativePath":"features/dashboard.md","filePath":"features/dashboard.md","lastUpdated":1779999197000}'),c={name:"features/dashboard.md"};function h(g,e,p,u,m,b){const o=i("ThemeImage");return d(),s("div",null,[e[0]||(e[0]=t("h1",{id:"dashboard-layout",tabindex:"-1"},[a("Dashboard & layout "),t("a",{class:"header-anchor",href:"#dashboard-layout","aria-label":'Permalink to "Dashboard & layout"'},"​")],-1)),e[1]||(e[1]=t("p",null,[a("The connected app is a "),t("strong",null,"dwindle binary-tree layout"),a(" of widget tiles, the same family of layouts you'd find in tiling window managers like Hyprland. Every tile has the same chrome — a header, an optional toolbar, the widget itself, and a corner grip — and they share every pixel of available space.")],-1)),n(o,{"src-dark":"/img/features/dashboard-multi.png","src-light":"/img/features/dashboard-multi-light.png",alt:"Dashboard layout"}),e[2]||(e[2]=l('<h2 id="adding-and-removing-widgets" tabindex="-1">Adding and removing widgets <a class="header-anchor" href="#adding-and-removing-widgets" aria-label="Permalink to &quot;Adding and removing widgets&quot;">​</a></h2><ul><li><strong>+ Add widget</strong> in the topbar opens the <a href="./settings#palette">palette</a>. Picking a kind splits the focused tile in two, with the new widget occupying half the previous space.</li><li><strong>× Close</strong> in a tile&#39;s header removes it. The surviving sibling expands to fill the freed area.</li><li><strong>Clear layout</strong> empties the dashboard back to its empty CTA. Useful when you want to redraw from scratch.</li></ul><h2 id="rearranging" tabindex="-1">Rearranging <a class="header-anchor" href="#rearranging" aria-label="Permalink to &quot;Rearranging&quot;">​</a></h2><ul><li><strong>Swap by dragging the header.</strong> Grab a tile by its header — the tile itself follows the cursor (at ~40% opacity so you can still see the drop zone underneath) with the same finger-on-tile grip you established on pointerdown — and drop it on another tile. They swap positions in the tree without resizing. Drop near an edge to split that side instead of swapping. The layout doesn&#39;t mutate until the drop fires — the cursor-follow is purely a visual preview.</li><li><strong>Drag affordances.</strong> The dragged tile wobbles slightly (iOS-icon-edit-mode style) and the inter-tile gap widens while a drag is active so the drop zones read more clearly. The wobble + gap bump are skipped in <strong>Performance mode</strong> (Global settings → Appearance) since they rely on the same layout transitions Performance mode disables; the dragged-tile transparency still applies so aiming a swap stays equally readable.</li><li><strong>Resize the seam.</strong> Hover the seam between two tiles; the cursor turns into a resize handle. Drag to redistribute space between siblings.</li><li><strong>Maximize.</strong> The square icon in a tile&#39;s header pops it to fill the entire dashboard. Click again (now a <em>Restore</em> icon) to drop back.</li><li><strong>Hide the chrome.</strong> The eye icon in the header cycles between <em>show everything</em> → <em>hide the toolbar</em> → <em>hide the toolbar <strong>and</strong> the header</em>. Use it when you want a tile to read like an embedded panel.</li></ul><h2 id="keyboard" tabindex="-1">Keyboard <a class="header-anchor" href="#keyboard" aria-label="Permalink to &quot;Keyboard&quot;">​</a></h2><p>The dashboard reads a small set of global shortcuts. None of them fire while the focus is inside a text field, so typing into a Logcat filter or Shell prompt is never affected.</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>⌘E</code> / <code>Ctrl+E</code></td><td>Open the quick-add menu (see below).</td></tr><tr><td><code>← ↑ ↓ →</code></td><td>Move the focused-tile ring to the spatially-adjacent tile.</td></tr><tr><td><code>Backspace</code> / <code>Del</code></td><td>Remove the focused tile. Inside the Files widget, deletes the selected entry instead (same as right-click → Delete).</td></tr><tr><td><code>⌘Z</code> / <code>Ctrl+Z</code></td><td>Undo the last layout-changing action.</td></tr><tr><td><code>⌘⇧Z</code> / <code>Ctrl+⇧+Z</code></td><td>Redo.</td></tr><tr><td><code>?</code></td><td>Open the keyboard-shortcut help dialog.</td></tr></tbody></table><h3 id="quick-add-menu" tabindex="-1">Quick-add menu <a class="header-anchor" href="#quick-add-menu" aria-label="Permalink to &quot;Quick-add menu&quot;">​</a></h3><p><code>⌘E</code> opens a Spotlight-style floating menu anchored at the focused tile (or centred at the top of the dashboard when there isn&#39;t one yet). Three ways to pick:</p><ul><li>Press a widget&#39;s single-letter accelerator — <code>L</code> (Logcat), <code>S</code> (Shell), <code>D</code> (Dumpsys), <code>F</code> (Files), <code>M</code> (Screen Mirror).</li><li>Use <code>↑</code> / <code>↓</code> to cycle the highlight and <code>Enter</code> to confirm.</li><li>Click the row directly.</li></ul><p>The <code>More…</code> row opens the full widget palette dialog with descriptions and capacity hints.</p><p>(The earlier prototype used <code>⌘N</code>, but macOS treats <code>⌘N</code> as a system-level &quot;new window&quot; shortcut the browser can&#39;t intercept. <code>⌘E</code> is unbound on every major browser + platform combination.)</p><p>The menu dismisses on Escape, outside-click, or any successful pick. Widgets that are at their <code>maxInstances</code> cap (Screen Mirror is hard- capped at 1) are greyed out and their accelerator is ignored.</p><h2 id="undo-and-redo" tabindex="-1">Undo and redo <a class="header-anchor" href="#undo-and-redo" aria-label="Permalink to &quot;Undo and redo&quot;">​</a></h2><ul><li><strong>⌘Z / Ctrl+Z</strong> undoes the last layout-changing action — adding a tile, removing it, swapping, resizing, maximize, clear-layout. The history buffer lives inside the tile grid; reloading the page persists the current layout but not the undo stack.</li><li><strong>⌘⇧Z / Ctrl+Shift+Z</strong> redoes.</li></ul><h2 id="persistence" tabindex="-1">Persistence <a class="header-anchor" href="#persistence" aria-label="Permalink to &quot;Persistence&quot;">​</a></h2><p>Layouts and per-widget settings persist in <code>localStorage</code>, globally per dashboard — not tied to a device serial:</p><ul><li>The tree itself: <code>weblogcat-dashboard-v2</code>.</li><li>Per-widget state: keyed by <code>weblogcat:settings:&lt;tileId&gt;:&lt;kind&gt;</code>, so two Logcat tiles keep independent filter setups across reloads.</li></ul><p>Because the keys are serial-free, your tiles and their settings stay put when you reconnect — including when the same phone reports a different serial over USB versus the Web Device Proxy, or when you plug in a different device entirely.</p><h2 id="sharing-a-layout-via-url" tabindex="-1">Sharing a layout via URL <a class="header-anchor" href="#sharing-a-layout-via-url" aria-label="Permalink to &quot;Sharing a layout via URL&quot;">​</a></h2><p>The dashboard URL accepts a <code>?d=&lt;encoded&gt;</code> query string that captures the current layout + tile settings. Clicking <strong>Share</strong> in the dashboard copies a link with the current state encoded. Recipients open the link, pair their own device, and land on your exact layout — chip filters and all.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>URL state is <strong>read-forward compatible</strong>: WebLogcat keeps accepting older <code>?d=</code> payload shapes so links you sent last month still resolve. See the note in <a href="./../devs/release-plan">release plan</a> for the long-term contract.</p></div>',22))])}const w=r(c,[["render",h]]);export{f as __pageData,w as default};
